// EF Core — LINQ translated to SQL by the framework
var orders = await dbContext.Orders
    .Where(o => o.OrderDate.Year == 2025)
    .Select(o => new OrderSummaryDto
    {
        Id = o.Id,
        CustomerName = o.Customer.FullName,
        Total = o.OrderItems.Sum(oi => oi.Quantity * oi.UnitPrice)
    })
    .ToListAsync();

// Dapper — you write the SQL, Dapper maps the results
await using var connection = new SqlConnection(_connectionString);
var orders = await connection.QueryAsync<OrderSummaryDto>(
    "SELECT o.Id, c.FullName AS CustomerName, " +
    "       SUM(oi.Quantity * oi.UnitPrice) AS Total " +
    "FROM Orders o " +
    "JOIN Customers c ON o.CustomerId = c.Id " +
    "JOIN OrderItems oi ON oi.OrderId = o.Id " +
    "WHERE YEAR(o.OrderDate) = @Year " +
    "GROUP BY o.Id, c.FullName",
    new { Year = 2025 });
